  recentCardio: `(()=>{const recent=[]; [...(DB.cardio||[])].reverse().forEach(c=>{ if(c.act&&CARDIO_ACTS[c.act]&&!recent.some(r=>r.act===c.act)&&recent.length<2)recent.push(c) }); return recent})()`,
  agoLabel: `(d=>{const n=dayDiff(d,today());return n===0?'Today':n===1?'Yesterday':fmtD(d,{weekday:'short'})})(__a[0])`,
  cardioStats: `cardioStats(__a[0],__a[1])`,
