/* ---------------- main ---------------- */
for (const tz of ['America/Toronto', 'UTC']) {
  const w = await loadWeb(tz);
  const scenarios = buildScenarios(w);
  const cases = buildCases(scenarios);
  const done = [], skipped = [];
  for (const c of cases) {
    if (c.pre && c.pre.presummary) {
      // run the finish for real, then read the summary off the resulting celebration
      const sc = scenarios[c.scenario];
      w.state.now = T(c.now);
      w.context.__json = JSON.stringify({profile: sc.profile, db: sc.db});
      w.run(`(()=>{const J=JSON.parse(__json); profile=J.profile; DB=J.db; rest=null; celebration=null; setActivePlan(); endSession(); __post=JSON.stringify({profile,db:DB,celebration})})()`);
      const post = JSON.parse(w.context.__post);
      const name = c.scenario + '_after';
      scenarios[name] = {profile: post.profile, db: post.db};
      const c2 = {...c, scenario: name, pre: {celebration: post.celebration}, snap: false};
      try { done.push(await runCase(w, c2, scenarios)); } catch (e) { skipped.push(c.id + ': ' + e.message); }
      continue;
    }
    try { done.push(await runCase(w, c, scenarios)); }
    catch (e) { skipped.push(c.id + ': ' + e.message); }
  }
  if (skipped.length) console.log(tz, 'skipped', skipped.length, 'cases that throw in the web app (out-of-range indexes):', skipped.filter(x=>x.startsWith('historyRow')).slice(0, 2).join(' | '));
  const used = new Set(done.map(c => c.scenario));
  const file = {tz, scenarios: Object.fromEntries([...used].map(k => [k, scenarios[k]])), cases: done};
  const name = `logic.${tz.replace('/', '_')}.json`;
  fs.writeFileSync(path.join(OUT, name), JSON.stringify(file));
  console.log(name, done.length, 'cases', Math.round(fs.statSync(path.join(OUT, name)).size / 1024), 'KB');
}
fs.writeFileSync(path.join(OUT, 'format.json'), JSON.stringify(await formatFixtures()));
{
  const w = await loadWeb('America/Toronto');
  fs.writeFileSync(path.join(OUT, 'catalog.json'), JSON.stringify(catalogJSON(w.run), null, 1) + '\n');
}
console.log('fixtures written');
